namespace HarmonyLib {[AttributeUsage(AttributeTargets.Method)]public sealed class HarmonyPriority:Attribute{public HarmonyPriority(int p){}}public static class Priority{public const int First=800,Last=0;}public sealed class HarmonyMethod{public MethodInfo Method;public HarmonyMethod(MethodInfo m){Method=m;}}public sealed class Harmony{public List<MethodInfo> Patched=new();public void Patch(MethodInfo m,HarmonyMethod? p,HarmonyMethod? q,object? t,HarmonyMethod? f,object? il){Patched.Add(m);}}}
namespace Il2CppSystem.Collections.Generic {public class List<T>:System.Collections.Generic.List<T>{public static int Created;public List(){Created++;}}}
public class Ptr{static long Next;public IntPtr Pointer{get;}=new(++Next);}
public enum UnitType{warrior,cloak,mermaidcloak,cloak_boat,dcp_spy,dcp_spymaid,dcp_mimic_form_dcp_spy,dcp_mimic_form_dcp_spymaid,dcp_mimic_form_cloak,dcp_mimic_form_mermaidcloak,dcp_mimic_form_cloak_boat,dcp_mimic_form_warrior}
public static class EnumCache<T>where T:struct,Enum{public static string GetName(T t)=>t.ToString();public static T GetType(string s)=>Enum.Parse<T>(s);}
[StructLayout(LayoutKind.Sequential)]public struct WorldCoordinates{public int x,y;public int X=>x;public int Y=>y;public WorldCoordinates(int x,int y){this.x=x;this.y=y;}}
public enum UnitEffect{Frozen=0,Invisible=3}
namespace Polytopia.Data{public sealed class UnitAbility{public enum Type{Dash=0,Hide=5}}public sealed class UnitData:Ptr{}}
public static class UnitDataExtensions{public static bool HasAbility(UnitState u,Polytopia.Data.UnitAbility.Type a)=>false;public static bool HasAbility(Polytopia.Data.UnitData d,Polytopia.Data.UnitAbility.Type a)=>false;}
public sealed class UnitState:Ptr{public Polytopia.Data.UnitData UnitData{get;set;}=new();public bool HasEffect(UnitEffect e)=>false;public uint id{get;set;}=1;public byte owner{get;set;}=1;public UnitType type{get;set;}=UnitType.dcp_mimic_form_cloak;public WorldCoordinates coordinates{get;set;}=new(0,0);}
public sealed class PlayerState:Ptr{public byte Id{get;set;}=1;}
public sealed class TileData:Ptr{public WorldCoordinates coordinates{get;set;}=new(0,0);public UnitState? unit{get;set;}public byte Owner=2;public bool City=true;public bool HasOpponentCity(byte p)=>City&&Owner!=0&&Owner!=p;}
public sealed class MapData:Ptr{public Dictionary<(int,int),TileData> Tiles=new();}
public sealed class GameState:Ptr{public uint CurrentTurn{get;set;}=4;public MapData Map{get;set;}=new();public PlayerState? Player=new();public bool Owned=true;public LedgerUnit? Row;public bool TryGetPlayer(byte p,out PlayerState? player){player=p==Player?.Id?Player:null;return player is not null;}public bool TryGetUnit(uint id,out UnitState? u){u=Map.Tiles.Values.Select(t=>t.unit).FirstOrDefault(u=>u?.id==id);return u is not null;}}
public static class PathFinder{public static object GetPath(GameState s,WorldCoordinates f,WorldCoordinates t,int n,UnitState u)=>new Il2CppSystem.Collections.Generic.List<WorldCoordinates>();public static Il2CppSystem.Collections.Generic.List<WorldCoordinates> GetMoveOptions(GameState s,WorldCoordinates start,int cost,UnitState u)=>new();}
public sealed class MoveCommand{public uint UnitId{get;set;}=1;public byte PlayerId{get;set;}=1;public WorldCoordinates From{get;set;}=new(0,0);public WorldCoordinates To{get;set;}=new(1,0);public bool IsValid(GameState s,ref string error)=>true;}
public static class MapDataExtensions{public static TileData? GetTile(MapData m,WorldCoordinates c)=>m.Tiles.GetValueOrDefault((c.x,c.y));}
namespace Deception.PolyModAdapter{internal static class NativeGameStateEnvelope{internal static object Frame=new();internal static object? Get(object state)=>Frame;}internal static class NativeRegroupSession{internal static bool Enabled=true;internal static int ReadyCalls,Reads;internal static bool Ready(object s){ReadyCalls++;return ((GameState)s).Owned;}internal static LedgerUnit? ReadIdentity(object s,uint id){Reads++;return ((GameState)s).Row is LedgerUnit r&&r.NativeId==id?r:null;}}}
namespace Deception.Tests{
 public static partial class CloakMovementTests{
 static int Cases,Assertions;static void Check(bool b,string why){Assertions++;if(!b)throw new Exception(why);}static void Test(string n,Action a){try{a();Cases++;}catch(Exception e){throw new Exception(n,e);}}
 static (GameState,UnitState,TileData) Make(string form="cloak",LedgerActualKind kind=LedgerActualKind.Mimic){NativeRegroupSession.Enabled=true;NativeRegroupSession.Reads=NativeRegroupSession.ReadyCalls=0;var s=new GameState();var u=new UnitState{type=kind==LedgerActualKind.Mimic?Enum.Parse<UnitType>(RecruitmentCatalog.Variant(form)):UnitType.warrior};s.Map.Tiles[(0,0)]=new(){unit=u,Owner=1};var tile=new TileData{coordinates=new(1,0)};s.Map.Tiles[(1,0)]=tile;s.Map.Tiles[(2,0)]=new(){coordinates=new(2,0),City=false};var a=new LedgerAppearance(form,new("imperius","default"),new("imperius","default"),new("imperius","default"),5,50,50,false,ApparentConcealment.Visible,-1,Array.Empty<string>());s.Row=new(1,1,true,kind,true,a,PaidInvestmentKind.Known,3);return(s,u,tile);}
 static object Options(GameState s,UnitState u,object original,WorldCoordinates? from=null){object? result=original;NativeCloakMovement.AfterOptions(s,from??u.coordinates,u,ref result);return result!;}
 static bool Allowed(GameState s,bool native=true,MoveCommand? command=null){string error="native";NativeCloakMovement.AfterMoveValid(command??new(),s,ref native,ref error);return native;}
 static Il2CppSystem.Collections.Generic.List<WorldCoordinates> Offered(params (int,int)[] cells){var x=new Il2CppSystem.Collections.Generic.List<WorldCoordinates>();foreach(var cell in cells)x.Add(new(cell.Item1,cell.Item2));return x;}
 static void SameOptions(GameState s,UnitState u){var x=Offered((1,0));Check(ReferenceEquals(Options(s,u,x),x)&&x.Count==1,"original unfiltered list preserved");}
 public static int Run(){try{
 Test("only supported detour signatures",()=>{var h=new HarmonyLib.Harmony();NativeCloakMovement.Install(h);Check(h.Patched.Select(x=>x.Name).SequenceEqual(new[]{"GetMoveOptions","GetPath","HasAbility","HasAbility","HasEffect","IsValid"}),"settings detour absent");var coord=h.Patched[0].GetParameters()[1].ParameterType;Check(coord.IsValueType&&Marshal.SizeOf(coord)==8&&coord.StructLayoutAttribute!.Value==LayoutKind.Sequential,"native coordinate uses true 8-byte CLR value");Check(h.Patched.SelectMany(m=>m.GetParameters()).All(p=>p.ParameterType.Name!="PathFinderSettings"),"no inline settings wrapper entry");Check(h.Patched[3].GetParameters()[0].ParameterType==typeof(Polytopia.Data.UnitData),"direct native data capability overload guarded");});
 foreach(string form in new[]{"cloak","mermaidcloak","cloak_boat"})foreach(byte owner in new byte[]{0,1,2})Test(form+" city owner"+owner,()=>{var(s,u,t)=Make(form);t.Owner=owner;var input=Offered((1,0));var output=Options(s,u,input);Check(((Il2CppSystem.Collections.Generic.List<WorldCoordinates>)output).Count==(owner==2?0:1),"only foreign occupied city filtered");Check(Allowed(s)==(owner!=2),"same authoritative command restriction");Check(input.Count==1&&ReferenceEquals(input,output)==(owner!=2),"clone only when changed, never mutate alias");Check(u.owner==1&&u.type==Enum.Parse<UnitType>(RecruitmentCatalog.Variant(form)),"no true body change");});
 Test("ordinary tile permits",()=>{var(s,u,t)=Make();t.City=false;SameOptions(s,u);Check(Allowed(s),"hostile territory alone not banned");});
 Test("genuine warrior cloak keeps real movement",()=>{var(s,u,t)=Make(kind:LedgerActualKind.Genuine);SameOptions(s,u);Check(Allowed(s)&&NativeRegroupSession.Reads==0&&NativeRegroupSession.ReadyCalls==0,"ordinary true body avoids ledger path");});
 Test("native cloak unchanged",()=>{var(s,u,t)=Make(kind:LedgerActualKind.Genuine);u.type=UnitType.cloak;s.Row=s.Row! with{Independent=false,Appearance=null};SameOptions(s,u);Check(!Allowed(s,false)&&Allowed(s,true)&&NativeRegroupSession.Reads==0,"native genuine result unchanged");});
 Test("ordinary mimic warrior permits",()=>{var(s,u,t)=Make("warrior");SameOptions(s,u);Check(Allowed(s)&&NativeRegroupSession.Reads==0&&NativeRegroupSession.ReadyCalls==0,"no blanket city ban or heavy ledger work");});
 Test("native denial and explanation preserved",()=>{var(s,u,t)=Make();bool allowed=false;string error="native denial";NativeCloakMovement.AfterMoveValid(new MoveCommand(),s,ref allowed,ref error);Check(!allowed&&error=="native denial"&&NativeRegroupSession.Reads==0,"veto only");});
 Test("forged actor refused by native policy guard",()=>{var(s,u,t)=Make();Check(Allowed(s,command:new(){PlayerId=2}),"foreign command not reinterpreted");});
 Test("wrong command source not borrowed",()=>{var(s,u,t)=Make();Check(Allowed(s,command:new(){From=new(2,0)}),"source exact");});
 Test("missing command actor unchanged",()=>{var(s,u,t)=Make();Check(Allowed(s,command:new(){UnitId=999}),"unknown actor native policy");});
 Test("same command destination",()=>{var(s,u,t)=Make();Check(Allowed(s,command:new(){To=new(2,0)}),"different ordinary tile allowed");});
 Test("rejection has explanation",()=>{var(s,u,t)=Make();bool allowed=true;string error="";NativeCloakMovement.AfterMoveValid(new MoveCommand(),s,ref allowed,ref error);Check(!allowed&&error.Length>0,"explain direct city denial");});
 Test("different query source unchanged",()=>{var(s,u,t)=Make();var input=Offered((1,0));Check(ReferenceEquals(Options(s,u,input,new(2,0)),input)&&NativeRegroupSession.Reads==0,"no foreign or hypothetical origin");});
 Test("filtered list retains order and duplicate legal cells",()=>{var(s,u,t)=Make();var input=Offered((2,0),(1,0),(0,0),(2,0));var output=(Il2CppSystem.Collections.Generic.List<WorldCoordinates>)Options(s,u,input);Check(output.Select(c=>c.x).SequenceEqual(new[]{2,0,2}),"only endpoints removed");Check(input.Select(c=>c.x).SequenceEqual(new[]{2,1,0,2}),"source and aliases intact");});
 Test("empty result preserves identity",()=>{var(s,u,t)=Make();var input=Offered();Check(ReferenceEquals(Options(s,u,input),input),"no pointless allocation");});
 Test("null result leaves ledger untouched",()=>{var(s,u,t)=Make();object? result=null;NativeCloakMovement.AfterOptions(s,u.coordinates,u,ref result);Check(result is null&&NativeRegroupSession.Reads==0,"native null preserved");});
 Test("native omitted legal destination stays omitted",()=>{var(s,u,t)=Make();var input=Offered((1,0));var result=(Il2CppSystem.Collections.Generic.List<WorldCoordinates>)Options(s,u,input);Check(result.Count==0,"no permissions added");});
 foreach(string mutation in new[]{"disabled","unowned","missing-player","wrong-player","foreign-unit","retired","missing-row","wrong-carrier","mismatched-form","nonindependent","genuine-row","different-world"})Test(mutation,()=>{var(s,u,t)=Make();switch(mutation){case "disabled":NativeRegroupSession.Enabled=false;break;case "unowned":s.Owned=false;break;case "missing-player":s.Player=null;break;case "wrong-player":s.Player!.Id=2;break;case "foreign-unit":u=new();break;case "retired":s.Row=s.Row! with{Alive=false};break;case "missing-row":s.Row=null;break;case "wrong-carrier":u.type=UnitType.dcp_mimic_form_warrior;break;case "mismatched-form":s.Row=s.Row! with{Appearance=s.Row.Appearance! with{Form="mermaidcloak"}};break;case "nonindependent":s.Row=s.Row! with{Independent=false};break;case "genuine-row":s.Row=s.Row! with{Kind=LedgerActualKind.Genuine};break;case "different-world":s=new();break;}SameOptions(s,u);});
 StealthMovementCases();
 Console.WriteLine(JsonSerializer.Serialize(new{passed=true,cases=Cases,assertions=Assertions,nativeGame="NOT RUN"}));return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
 }
}
